quests[71042] = { id = 71042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Titan Relic", progress = "Have you found a Titan Relic?", completion = "Amazing! This relic is perfectly preserved. I will begin studying it right away.\n\nYour efforts are most appreciated! I will remember my promise to speak well of you to the Valdrakken Accord. \n\nNow, where was I? Yes, this will fit in right over here..." }
quests[71043] = { id = 71043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Titan Relics", progress = "What have you brought me today?", completion = "How did you find so many of these? This is a veritable treasure trove of relics! One day you must tell me your secret. \n\nOnce again you have greatly increased our knowledge of the titans. The Valdrakken Accord will think well of you indeed!" }
quests[71053] = { id = 71053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hermit Kill Quest", description = "Help! all these bunnies are eating my flesh! Please, kill them before they kill us all!", objectives = "Kill 5 Bunny of Doom in Training Plaza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71058] = { id = 71058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observing the Wind", objectives = "{name}, you are a dragonrider, yes? You show great promise as an ally.\n\nLet me give you this, then, to celebrate our growing alliance. And I promise there is more where that came from!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71060] = { id = 71060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Adorn Your Head", objectives = "Your deeds honor your people, friend {name}. Please accept this helm as a gift in recognition of all that you do for us. \n\nShould you find yourself wanting more, I would be happy to trade with you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71066] = { id = 71066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Useful Curiosity", objectives = "{name}, you are in luck. One of our crafters created shoes we think you could use. Sky only sees why, but your service to the clan has inspired at least one of us.\n\nHowever, as much as I'd like to, we can't simply give them away. It was costly to create just a single pair of your unusual footwear. But they will be here if you should need them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71067] = { id = 71067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whistling Rocks", objectives = "Dragonrider! The Aylaag understand that navigating to their camp can be challenging. And you know them--they welcome anyone who will follow their ways.\n\nOne of their nomads dropped off these windstones for you. They are not well-enchanted, but will transport you to the Aylaag camp. A few times, at least. Should that enchantment fade, they could likely make more!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71073] = { id = 71073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantle of Friendship", objectives = "My friend! It's a joy to see you again. I have another gift for you!\n\nPlease, take it with my compliments. But don't tell Huseng that I'm giving it away. He wanted me to charge you for it!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71074] = { id = 71074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befriending Wings and Wind", objectives = "You're just in time, dragonrider. I have a special acquisition from the Ohn'ir. \n\nWith our clans spread so far apart, we often rely on ohuna to relay critical messages. This will allow you to call upon our eagle mail carriers wherever you go. They're not the swiftest, but they are reliable.\n\nNormally I would require a trade, but this is too important a boon. You may have need of it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71075] = { id = 71075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding Their Grace", objectives = "Ah, my friend, you have returned! We were just speaking of how helpful you are!\n\nHere, accept this gift. It is the least we can do for an ally.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71079] = { id = 71079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting to the Point", objectives = "So they've finally sent you to me, have they? Excellent!\n\nI stock many fine weapons for you to consider. Normally I'd insist on trading for my goods, but today I wish to honor your deeds for my people.\n\nJust don't tell Huseng. He'd never let me hear the end of it if he knew I gave something away... even to a dragonrider.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71083] = { id = 71083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Expected Unexpected Gift", objectives = "Dragonrider! Some of our goods are missing. \n\nI'd bet my back hooves that it's Rondare being too generous again. I've made clear that she can't just give things away. Seems I must have yet another chat with her.\n\n<Huseng grumbles, then realizes something.>\n\nOh, I almost forgot. I wanted to give you this.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71085] = { id = 71085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Representation Matters", objectives = "Ah, dragonrider. The clans have been sharing tales of your deeds for several moons now.\n\nThey've all asked that I make your next gift a pennant of their clan's colors so you can represent them on the battlefield. Trouble is, I can only spare one of them. Huseng's on to me.\n\nWhich would you choose?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71089] = { id = 71089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get on the Horn", objectives = "Friend, the Shikaar have asked me to offer you their ritual hunting horns. They insisted the horns were only for you, and that I was not to use them.\n\nHmph! I'm an excellent hunter. Perhaps the best they will ever see! They just don't know it yet.\n\n<Huseng laughs.>\n\nSo here you are. My stock is open to you, should you want any others.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71090] = { id = 71090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Heart, For the Heart", objectives = "Ah, dragonrider. I have something for you.\n\n<Huseng holds up chest armor, sized for a {race}.>\n\nWe had to, uh, scale it down to fit you. It is fine make. Too fine to simply give it away. But I can sell it to you for the cost of materials.\n\nYou have proven yourself an ally of the Maruuk. Time for you to look the part!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71091] = { id = 71091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highest Honor", objectives = "My friend, you have defended these plains alongside my people, lending your aid to each of our clans without hesitation. You are an outsider no longer, but a familiar face among the centaur.\n\nTo honor our bond, I anoint you with the title of Khansguard and present you with this gift. May you proudly bear the Maruuk name wherever your travels take you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71093] = { id = 71093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of Tyr: Secrets of the Past", description = "To stop Raszageth from freeing the other Incarnates, the power of the Aspects must be restored.\n\nInconveniently, the Titans are rather preoccupied and Keeper Tyr is long dead.\n\nQueen Alexstrasza has suggested a plan. In the depths of the Badlands lies a Titan facility called Uldaman. Apparently allies of Tyr may have hidden a disc of his memories there.\n \nWord is that the place has been overrun by troggs. Gather your allies, head to Uldaman, and seize the disc in the name of the Dragon Queen!", objectives = "Enter Uldaman: Legacy of Tyr in the Badlands and recover the disc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71094] = { id = 71094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Is Our Way!", description = "Hiya! \n\nAre you also here to help? You look very helpful!\n\n<Heleth points to the injured dracthyr.>\n\nThat guy hurt his wing trying to fly all the way up here! He looks like one of those bad guys from downstairs, but I'm not scared of him! I'm gonna help him out anyway, because that's our way!\n\n<Heleth puffs out their chest.> \n\nI'll stand guard over him, while you go find some bandages!", progress = "Finally! New people to play with!", completion = "We're gonna help this bad guy out so good!", objectives = "Find bandages in the tower above the Cobalt Assembly to heal Venderthvan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71095] = { id = 71095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Claw in Need", description = "Let's see what we can do to help this guy!\n\n<Heleth leans in close and whispers.>\n\nDon't worry, we aren't gonna let him take anything or stuff like that. Let's just have some fun!\n\nIt's been ages since anyone has come up here to check up on us. We're SO bored!\n\n<Heleth winks at you.> \n\nWhy don't you ask him what he wants?", progress = "Go ahead, {race}, do all the work for me. It will be a piece of cake to take the artifact from you when the moment is right.", completion = "That looks promising. Give it here. \n\n...what do you mean you're not going to give it to me?", objectives = "Ask Venderthvan how you can help him and do what he says.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71096] = { id = 71096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is A Claw Indeed", description = "<Venderthven rubs his eyes and groans in pain.>\n\nFine. If you won't give it to me, you can do the work of figuring out how to make it work. \n\nI'll just take it from you when you're done. By force, if necessary.\n\nSo go ahead. Give it a shake or something.", progress = "<Venderthvan is distracted, looking at a toy duck Nezzie is showing him.>", completion = "Huh? Oh, right. The arcana.", objectives = "Attempt to activate the artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71097] = { id = 71097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Helping Claw", description = "Alright, you've charged the artifact. Let's turn it on.\n\nAnd stop giving me that look. Don't pretend like you aren't curious to see if it works. \n\nJust give that thing another shake, back away slowly, and let me finish the job.", progress = "<Venderthvan looks distracted.>", completion = "Enough... enough!\n\nI didn't sign up for this. \n\nJust take the artifact. Before I think too hard about this and change my mind.", objectives = "Activate the artifact in the tower above Cobalt Assembly and monitor Venderthvan's actions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71135] = { id = 71135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loose Ends", description = "If there's anything I learned from my time out in the wilderness, it's that if you don't deal with an evil when you find it--if you don't break its bones and dig up its roots, it'll keep growing. And then it'll be harder to kill.\n\nThese mountains were plagued with Frostbite's existence when I was a young pup like you, and it will only get worse once he takes full control of the Snowhide tribe. \n\nI should have done something about him long ago, but we're the only ones who can right that mistake now.", progress = "We cannot rest until Frostbite and the Snowhide gnolls have been dealt with.", completion = "Let's never do this again.", objectives = "Confront Frostbite at the Snowhide Camp in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71138] = { id = 71138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waygate: Rusza'thar Reach", description = "An expeditionary member reported a dormant stone sighting atop a lookout in the Ohn'ahran Plains.\n\nUp fer an adventure?", progress = "What are ye waitin' fer?", completion = "Up and runnin' already? That was quick!\n\nI'll hold onto this here vessel. Looks like it's still got some energy wizzin' about!\n\nNever know if if we'll be needin' it again.", objectives = "Locate the Dormant Waygate at the Rusza'thar Reach in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71139] = { id = 71139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glowing Arcane Jewel", description = "<This jewel seems to be quite powerful. There is an eerie glow to it.\n\nPerhaps it's best to deliver it to the Kirin Tor for it to be placed in a safe spot.>", completion = "Look at this jewel! I'll make sure it gets to Dalaran immediately for study. \n\nHere, take this for your efforts. We recently uncovered it from another excavation.", objectives = "Bring the Glowing Arcane Jewel to Noriko the All Knowing in Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71140] = { id = 71140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two and Two Together", objectives = "Defeat Bakhushek in a Pet Battle", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71141] = { id = 71141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gills with Gall", description = "Kad'irsza is reckless, but she knows her crabs. The gorlocs have gone too far!\n\nI noticed the gorlocs going to Gurblbrblr for everything. Notably, he is instructing them to take crabs prisoner. We cannot allow this to continue, for the balance of life, and for the safety of those who tend it.\n\nDefeat Gurblbrblr. Remove their means of expanding beyond this river!", progress = "Do not permit the gorlocs to encroach on the wildlife!", completion = "Good. Now the gorlocs will lack the wherewithal to shackle more of these crabs. \n\n... And you have done more than just protect the crabs, {name}. You have protected Kad'irsza as well. I thank you.", objectives = "Kill Gurblbrblr the Invader in Cliffdrip Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71143] = { id = 71143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Slayer", description = "Wow! Keep it up, soldier! \n\nSlay a bit more Horde and you will go down in the record books among the Alliance. \n\nBut it won't be easy, the Horde have put a bounty on your head, so watch it!\n\nFor the Alliance!", objectives = "While being hunted by the Horde, slay 10 Horde without dying.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71144] = { id = 71144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Slayer", description = "Yes! Keep going, keep slaying those Alliance dogs!\n\nSlay a bit more Alliance and you may set a new record, {class}.\n\nBut it won't be easy, the Alliance have put a bounty on your head, so watch it!\n\nFor the Horde!", objectives = "With a bounty on your head, slay 10 Alliance without dying.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71145] = { id = 71145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Master", objectives = "Defeat Patchu in a Pet Battle", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71146] = { id = 71146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Waygate Exploration", description = "<The explorer-in-training hands you a taut, rolled note. Upon investigating, it appears to be from an old friend, Thaelin Darkanvil, seeking your aid.\n\nBefore scurrying off, the critter extends its hand as if it were seeking a treat. Moments later, a loud screech rings out as the curious creature storms off empty handed.>", completion = "Ah, my favorite friend returns fer a new adventure!\n\nOh, that's between us just so ye know. Wouldn't want the others tae think they aren't my favorite too!", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71148] = { id = 71148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Waygate Exploration", description = "<The curious creature before you presents a note--signed and sealed by the Dragonscale Expedition.\n\nA call for assistance from a famed explorer, perhaps.>", completion = "What do we have here? It's my most adventurous... erm... adventurer!\n\nCome tae do a bit more explorin'?", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71149] = { id = 71149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Waygate Exploration", description = "<Surprisingly, the messenger did not leave you with a satchel or a note this time, rather a single item from Thaelin's personal collection.\n\nUpon further investigation, a tiny little message from Thaelin seeks your assistance once again.>", completion = "Can't get enough, can ye?\n\nGlad tae see ye again, {name}! Let's get to it.", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71150] = { id = 71150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Waygate Exploration", description = "<The parchment emits an unpleasant, mold-like smell. After struggling to regain focus, it becomes clear Thaelin needs your assistance in seeking answers to newly discovered findings.\n\nThe only question that remains is what to do with this parchment of intolerable odor.>", completion = "Ack, ye scared me! Wasn't expectin' ye so soon.\n\nUp fer a bit more explorin' I see.", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71151] = { id = 71151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Waygate Exploration", description = "<The letter is clean, crisp and bears the seal of the Dragonscale Expedition.\n\nThaelin Darkanvil requests your presence.>", completion = "The famed explorer returns! I've grown quite fond of our time together, {name}.\n\nWhat say you? Up fer one last hurrah?", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71152] = { id = 71152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Main Hall", description = "Now that we've accessed the override consoles, we should be able to get past that barrier.\n\nI'll meet ye back in the main hall and we'll see this through!", completion = "All that hard work is about to pay off, {name}.", objectives = "Rendezvous with Toddy in the main hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71153] = { id = 71153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WQs, Bonus Objectives and Scenarios Oh My", description = "Assist the Tortollan by completing 3 world quests.", objectives = "Complete 3 Tortollan world quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71154] = { id = 71154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talon Toss: Shooting 101" }
quests[71155] = { id = 71155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azure Vaults", description = "We have a problem, {name}.\n\nBeneath the Azure Archives rests the Azure Vault. In my life, I stored many important and dangerous magical curiosities in it.\n\nA large group of Sundered Flame have broken into the vault, convinced it holds some kind of secrets.\n\nPlease, you must go in there and stop this brazen assault before they unleash dangers they do not comprehend.\n\nThese thieves know not what lies within.", progress = "Do be careful within the vaults.", completion = "Ten thousand years of delaying what I feared in my heart would be the inevitable end for my child. \n\nMalygos and I hoped one day we would find a cure. Though that day never came, I would not change any of our actions.\n\nWe must always strive for hope, even if it seems nonexistent. \n\nI take comfort in knowing at least my child is now reunited with the true Sindragosa and Malygos.\n\nNow go.", objectives = "Stop the Sundered Flame within the Azure Vaults.\n\nYou can access the Azure Vaults solo by queuing for it in Follower Dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71156] = { id = 71156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebel Concerns" }
quests[71157] = { id = 71157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waygate: Skytop Observatory", description = "Word from some of our northern explorers is there's another o' those stones high atop the spire to the northeast.\n\nHeard it's quite difficult tae reach bein' so high up and all, but I'm sure ye can find a way!", progress = "Any luck?", completion = "The spire-seeker returns!\n\nHope it wasn't too much trouble fer ya.", objectives = "Locate the Dormant Waygate at the Skytop Observatory in The Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71160] = { id = 71160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Depth Charge" }
quests[71161] = { id = 71161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waygate: Vakthros", description = "Received a report of another of them dormant stones in the wintry region tae the southeast.\n\nNow before ye go gettin' all excited just know this isn't a place most go willingly, but if ye feel the need fer adventure and possible death, this is fer you!\n\nSold ye on it enough yet? Good!\n\nToss on yer warmest attire, then head east until the chill of the wind tickles yer nose and keep goin'. You'll know yer close when ye start feelin' the toughness in yer breath and the chill in yer bones.", progress = "Keepin' warm I hope.", completion = "Bit chilly, wasn't it?\n\nNow that that's o'er and done with, what's next on yer agenda?", objectives = "Locate the Dormant Waygate atop the spire in Vakthros in The Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71162] = { id = 71162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waygate: Algeth'era", description = "Another stone. Another spire.\n\nBest be gettin' along on yer journey. This one's quite a trek and dangerous tae boot! At least accordin' tae the ones who discovered it.\n\nAre ye up fer it?", progress = "Can always count on ye tae get the job done.", completion = "I'm startin' tae wonder when this vessel might run out of power. Errr, maybe I'm the only one thinkin' that.\n\nWhat's in this thing anyways?\n\n<Thaelin shakes the vessel, but it makes no sound.>", objectives = "Locate the Dormant Waygate atop the spire in Algeth'era in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71164] = { id = 71164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Bandages" }
quests[71165] = { id = 71165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waygate: Eon's Fringe", description = "Far across the land in the mountainous regions of Thaldraszus sits a little inn nestled on the mountainside. Just inside the entryway sits a long-forgotten, dormant stone.\n\nWhat say ye? Up fer another adventure, {name}?", progress = "Ye know I'd love tae sit around and talk, but there's work tae do.", completion = "Yer adventurous nature never ceases tae amaze!\n\nI wonder how many more o' these things are out there.", objectives = "Locate the Dormant Waygate at Eon's Fringe in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71166] = { id = 71166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Oldest Dragonfly", objectives = "Defeat Swog in a Pet Battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71178] = { id = 71178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waygate: Shady Sanctuary", description = "Our expedition reports a dormant stone out in the lush hillsides to the southwest. It's quite a journey, but worth sendin' someone with yer knowledge tae investigate.", progress = "Well? Get on with it!", completion = "Looks like it worked!\n\nI'll keep the vessel safe in case we'll be needin' it again.", objectives = "Locate the Dormant Waygate at the Shady Sanctuary in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71179] = { id = 71179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Look to the Overlook", description = "{name}, I have another task for you.\n\nThere have been reports of Primalist activity near the Gelikyr Post that threaten our control of Tyrhold.\n\nSpeak with Commander Thadezus and see how you can assist.", completion = "<Thadezus sighs deeply.>\n\nYou are telling me that Drine sent you?", objectives = "Speak with Commander Thadezus at the Gelikyr Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71180] = { id = 71180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Have to Start Somewhere", objectives = "Defeat Setimothes in a Pet Battle", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71181] = { id = 71181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgotten Grotto Relics" }
quests[71182] = { id = 71182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wayward Archivists", description = "You, dracthyr. \n\nTwo of your kin have been searching the archives just south of here. I have yet to introduce myself, and would appreciate the company.\n\nIf you have the time, I can meet you in the upper archive.", completion = "You are a very jumpy bunch.", objectives = "Meet Sindragosa in the upper archive in the Azure Archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71191] = { id = 71191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Net Worth", description = "Alas, my fishing net was carried away by the stream. <Sigh> I'm not too keen to use fishing poles like my friends...\nIf you happen to find my fishing net around, bring it back to me.", progress = "Any luck finding the net?", completion = "You you found it! Alas, too late, I've got a replacement from Tavio in Iskaara already. Feel free to keep it, it's best fit for catching fish in these icy waters.", objectives = "Recover Gruff Fisher's Net from ice holes in Azure Span.\n\nYou may unlock only one extra fishing net per day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71192] = { id = 71192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Predator Control", description = "Greetings friend!\n\nI've been looking for a good place to set up fishing nets around here, but it seems like the population of waddlers around here is too dense - they're eating away most of the juvenile fish before they get a chance to mature.\n\nI've made some effigies to scare at least some of those ravenous birds away. This will help us sustain the abundance of fish across the Dragonsprings. \n\nCan you help me set those up?", progress = "Did you set up enough effigies?", completion = "Well done, my friend! Feel free to set another fishing net now, there should be enough us all.", objectives = "Set up the Scary Effigies.\n\nYou may unlock only one extra fishing net per day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71193] = { id = 71193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underwater Menace", description = "Did you see that? Underwater! A huge, armored, hungry beast! No way I'm getting near water with my net while that monstrosity lurks below. If you want, you can likely lure it out with a handful of Ominous Conches. Those shouldn't be too hard to catch.\n\nTo gain conchs, be sure to have your Iskaaran Harpoon handy as you fish in the Dragon Isles.", progress = "You're not afraid of littoral megafauna, are you? Because I am!", completion = "You don't mind sharing some of the meat with me? Why thank you, let me show you the best fishing net spot around in return.", objectives = "Use 5 Ominous Conches in the Tyrhold Fishing Hole to summon a huge underwater beast, and bring back something as a proof of its demise.\n\nYou may unlock only one extra fishing net per day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71194] = { id = 71194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frogs of Fire", description = "I found a perfect spot for a fishing net, one problem bothers me though... Those Hornspikes. I'm pretty sure they will ravage the nets as soon as it's left alone. What do we do?\n\n...I've got an idea. We treat our lava fishing nets with Icicle Brew to make them heat-resistant. We just need to teach those hornspikes to keep away from that smell.\n\nToss a flask of Icicle Brew at a hornspike, and then deal some damage to them. Just make sure not to kill them, they won't learn if they're dead, would they?", progress = "Did you teach them to keep away from the smell of Icicle Brew?", completion = "Well done! Feel free to use the fishing net spot now, there's enough room for us all.", objectives = "Teach a couple of Hornspikes to avoid Icicle Brew.\n\nYou may unlock only one extra fishing net per day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71195] = { id = 71195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Tame A Thunderspine", description = "I guess this is Lizi's new favorite spot. She hasn't been interested in coming back home. After all, she is a wild beast.\n\nI have to tell you... I haven't spoken to Meluun since we saved Lizi. I know she was right, but I don't know how to approach her. She doesn't seem to approve of anything I do. I know I have to focus more on my training.\n\nMeluun makes a stomping good curry that Lizi would love. Do you think you could ask her for it? She's usually working in the Ohn's house west of the springs.", progress = "Did you talk to Meluun yet?", completion = "I can smell the curry from here! Oh, by the ancestors, Lizi will be so happy! I'll take this as a sign that Meluun hasn't cast me out of her good graces completely.", objectives = "Collect Meluun's Green Curry in the Ohn'iri Springs and 150 Dragon Isles Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71196] = { id = 71196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Tame A Thunderspine", description = "I'm so happy that Lizi is safe and sound with us.\n\nHowever, her wounds are healing slower than expected. I hope that the magic inflicted upon her didn't cause permanent damage.\n\nCould you help me gather insect ichor? I know, it sounds gross! It's actually the base of many healing ointments.", progress = "Have you returned with more ichor? I hate to see Lizi still in pain.", completion = "I'll go apply it to her wounds right away. It should offer immediate relief.", objectives = "Collect 20 Fluorescent Fluid from insects around the Dragon Isles and 150 Dragon Isles Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71197] = { id = 71197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Tame A Thunderspine", progress = "Lizi is healed, but she's still nervous about leaving her spot. In the wild, she'd forage about a musken's weight of plants a day. It's impossible for me to do that! We need her to move out of the water and to the grasses.\n\nI'll keep trying to coax her out, but in the meantime, could you help me forage? I hear there are especially nutritious high-fiber leaves in the Emerald Gardens. Please bring back any you can find!", completion = "This should tide her over until she can forage by herself again." }
quests[71198] = { id = 71198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Tame A Thunderspine", progress = "Lizi's doing so much better. She's moving around with ease and consuming everything edible in sight.\n\nI learned today that thunderspines enjoy eating fish--especially piranhas! How fascinating! It is how they keep the piranha population in check at home.\n\nWill you go fish some? Mind your fingers!", completion = "Those piranhas sure look...crunchy. I'm glad a predator exists for them." }
quests[71199] = { id = 71199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Tame A Thunderspine", progress = "Everyone is curious about Lizi, but the truth is, she sticks out like a sore hoof. Lizi herself is starting to wander more and more, as if she's looking for something.\n\nShe mostly rests by the water on the mud. I'm sure it's fine, but I know thunderspines like to make a bedding from grasses.\n\nI've got an idea better than grasses. Will you help me gather wool from the plains? I'll weave her a blanket and some toys.", completion = "Perfect! This will do! I've not met an animal that doesn't like soft things." }
quests[71202] = { id = 71202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mini Manafiend Melee", objectives = "Defeat Arcantus in a Pet Battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71205] = { id = 71205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hydro Tuskarr" }
quests[71206] = { id = 71206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of the Stormling", objectives = "Defeat Stormamu in a Pet Battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71209] = { id = 71209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beast of the Plains", completion = "Don't forget to visit me sometime! Goodbye, {name}!", objectives = "Accept Lizi's Reins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71210] = { id = 71210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Dragonbane Keep!", description = "<Flaps drops a slightly singed note into your hand.>\n\n{name}, the Obsidian Outcasts have heard tales of your bravery. Our former home, Dragonbane Keep, has fallen into djaradin hands. We can't let that stand. Join us in reclaiming our territory.\n\n- Boss", progress = "We must take the Keep!", completion = "Another battle is won, but the war continues.", objectives = "Travel to the Waking Shores and join the Obsidian Outcasts on the Siege of Dragonbane Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71212] = { id = 71212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attackin' the Brackenhide" }
quests[71219] = { id = 71219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wayward Waywatcher", description = "It seems some of our younger Waywatchers have grown lax in their duties of late.\n\nWaywatcher Nori has asked me to check in on her younger sister Alvi, who is stationed at the mouth of the Passage of Time. Apparently her recent performance has been less than satisfactory.\n\nIf you head east and happen to encounter Waywatcher Alvi, please remind her of the importance of her position, and let her know that her sister is rather worried about her.", completion = "Oh, gracious, a traveler. Please forgive me, I am a bit of a mess at the moment.", objectives = "Find Waywatcher Alvi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71225] = { id = 71225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blown Through Wind: Rhuzast" }
quests[71226] = { id = 71226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Rock Snails", description = "Help! all these bunnies are eating my flesh! Please, kill them before they kill us all!", objectives = "Kill 5 Bunny of Doom in Training Plaza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71227] = { id = 71227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Challenges", description = "<Flaps flaps his wings excitedly, dropping both a note and a singed rodent at your feet.>\n\nDragonrider! Your flight prowess has become well known. Come test yourself in Aerial Challenges across the Dragon Isles.\n\nSpeak to any Bronze Timekeeper to get started.", completion = "Another challenger? Welcome! \n\nAerial Challenges are timed races on courses throughout the Dragon Isles. Beat track times to earn your rank.", objectives = "Speak to a Bronze Timekeeper to learn about aerial challenges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71229] = { id = 71229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Plains", description = "<Roki drops a message into your hand.>\n\n{name}, Clan Aylaag has heard tales of your great deeds. We invite you to meet our clan and share our ways.\n\nHadari Khan", completion = "Your aid is welcome, Dragonrider. There is much to be done around our camp.", objectives = "Speak to Hadari Khan in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71230] = { id = 71230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuskarr Fishing Gear", description = "Hi again, {name}.\n\n<Rowie looks around and hums a little tune.>\n\nOh right! Tavio was making me a new net and said she could make you one too. She can make some other fishing gear too if you bring her all the stuff.\n\nYou should go talk to her.", completion = "My family is known as the best weavers of nets and crafters of harpoons. If you bring me the supplies I need, I can craft some new tools for you.", objectives = "Speak to Tavio at Iskaara in The Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71231] = { id = 71231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Hunt", description = "<Roki drops the note into your hand>\n\n{name}, Clan Shikaar invites you to the Grand Hunt. Meet with Trainer Frodrum in the Ohn'ahran Plains.", completion = "Dragonrider! Your aid will be welcome in the coming hunts.", objectives = "Speak to Trainer Frodrum in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71232] = { id = 71232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renown of the Dragon Isles", description = "There is still much that must be done to aid the Dragon Isles.\n\nI would ask you speak with Koszaru. He has much information regarding who needs help within this land.", completion = "Good to see you, {name}. \n\nThere are many sources of power within the Dragon Isles, as long as you know where to look!", objectives = "Speak with Koszaru within Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71233] = { id = 71233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falling Water", description = "I love waterfalls. \n\nWant to know what's better than a waterfall? \n\nTwo waterfalls. \n\nAnd the only thing better than that is... well, check out Three-Falls to the west of here and you'll see!\n\nThe innkeeper there is quite nice.", completion = "Welcome to Three-Falls Lookout! \n\nWe're pretty high up, and there's rushing water everywhere--so look out!", objectives = "Talk to Willa at Three-Falls Lookout in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71234] = { id = 71234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nook News", description = "You there, {race}. \n\nYou look well-travelled. \n\nMy cousin Wayun was bringing a catch over from Whaler's Nook and mentioned that some... strange folk have set up camp over there.\n\nThey appear to be behaving themselves, but would you mind checking in on Wayun?\n\nHe can be a bit salty.", completion = "Another one?\n\nOh joy.", objectives = "Visit Whaler's Nook in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71235] = { id = 71235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Mages", description = "Lok'tar, {race}. \n\nIf you have the time, we have two mages doing fieldwork nearby who I'm sure could use a hand.\n\nThis is a dangerous land in the best of times. \n\nThese are not the best of times.", completion = "We don't need your help.\n\nBut we'll take it.", objectives = "Check on the Kirin Tor mages near Slyvern Plunge in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71238] = { id = 71238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruby Feast!", description = "Attention to all aspiring culinarians!\n\nDoes your heart desire the ultimate flavors of this world? Do you seek out opportunities for grand exploration? Are you willing to risk life and limb for complete strangers?\n\nIf this is you, come speak with the eminently distinguished, world-renowned chef duo, Rumiastrasza and Morsel! Currently hosting The Ruby Feast in the city of Valdrakken!", completion = "Is this about the posters? Did they actually work?!", objectives = "Speak with Chefs Rumiastrasza and Morsel at The Ruby Feast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71239] = { id = 71239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost to the Skies", description = "I need a favor, and you look like the favor-doing type.\n\nAn ol' pal of mine, Harleen Chirpsnide, was supposed to meet me in the city a few days ago. We was planning to eat our way through The Ruby Feast, get a trim at the barbershop, then visit that swanky auction house they got here.\n\nBut she ain't shown up. She gets lost in her work plenty, but I'd feel a lot more comfortable knowing where she was.\n\nTry the mountains south of here. She mentioned she'd be swinging by on her way in.", completion = "Ol' Fizzlecrank is worried, eh? Guess the drinks are on me when I finish up here.", objectives = "Locate Harleen Chirpsnide in the Bluefeather Cliffs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71241] = { id = 71241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duck, Duck, Trap", description = "The grove called the Primordial Vale is rich with the magic of the old dragons. A type of slyvern there are prized by my kin for their fur, but they are elusive and hard to find.\n\nInstead of having you try to track them down, you can find some of our hunting traps in the area. Use meat from the nearby waterfowl to reset them - I will send some of our clan to retrieve whatever gets caught.", progress = "The fowl in the area are the preferred source of food for the slyverns.", completion = "Thank you. Our clan will hopefully be able to use the resulting pelts for trade.", objectives = "Reset the Clan Aylaag hunting traps at the Primordial Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71242] = { id = 71242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supporting the Storm Researchers", description = "This looks like a large cluster of overflowing power from creatures within the Primalist Storm.\n\nThere's bound to be a researcher in Valdrakken who'll want this.", completion = "Oh, marvelous! This is just what we were looking for, thank you.", objectives = "Bring the Elemental Overflow Cluster to a researcher in Valdrakken.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72008] = { id = 72008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overcoming A Mountain: Krolkoth" }
