quests[72039] = { id = 72039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", objectives = "Your deeds are essential to our expedition's success in the Dragon Isles. To that end, I have been authorized to issue this supply allotment to assist you. Keep up the good work, adventurer!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72040] = { id = 72040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", objectives = "Welcome back, adventurer. Looks like you've been authorized a supply allotment increase. Good for you! You certainly have earned it. I know I've told you this before, but we appreciate your help and look forward to what you'll do next!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72041] = { id = 72041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", objectives = "Welcome back, adventurer. I am glad that I have been authorized to increase your supply allotment, as you certainly have earned it. I know I tell you this all the time, but I do hope you continue to aid our efforts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
